#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>
int main() {
    try {
        std::string raw = "{\"a\":123,\"b\":[true,false,null],\"c\":\"hello\"}";
        nlohmann::json_document doc = nlohmann::json_document::parse(raw);
        nlohmann::json_view view(doc);
        std::cout << view.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXC: " << e.what() << std::endl;
    }
}
